-- Owner-approved 36-piece family option. Preserve other sizes, products and historic orders.
UPDATE products SET settings=jsonb_set(jsonb_set(jsonb_set(settings, '{option_groups}',
 (SELECT jsonb_agg(CASE WHEN g->>'code'='SIZE' THEN jsonb_set(g,'{values}',(SELECT jsonb_agg(v) FROM jsonb_array_elements(g->'values') v WHERE v->>'code'<>'v-f79d0c0c352f2bb2fc40e13a') || '[{"code": "v-f79d0c0c352f2bb2fc40e13a", "name": "عائلي · ٣٦ حبة (١٨ ملفوف + ١٨ ورق عنب)", "name_en": "Family · 36 pieces (18 cabbage + 18 grape leaves)", "price_delta_halalas": 0}]'::jsonb) ELSE g END) FROM jsonb_array_elements(settings->'option_groups') g)),
 '{variant_price_matrix}', (SELECT coalesce(jsonb_agg(r),'[]'::jsonb) FROM jsonb_array_elements(settings->'variant_price_matrix') r WHERE r->'options'->>'SIZE'<>'v-f79d0c0c352f2bb2fc40e13a') || '[{"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-91f67e8b7351adcf1014135a"}, "price_halalas": 4550, "compare_at_halalas": 6200}, {"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-37d0336de98e6dc7d6d50959"}, "price_halalas": 4550, "compare_at_halalas": 6200}, {"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-7b580db54a84af523166d2da"}, "price_halalas": 4550, "compare_at_halalas": 6200}, {"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-2606b799a8a89a992bffd12e"}, "price_halalas": 4550, "compare_at_halalas": 6200}]'::jsonb),
 '{variant_images}', (SELECT coalesce(jsonb_agg(r),'[]'::jsonb) FROM jsonb_array_elements(settings->'variant_images') r WHERE r->'options'->>'SIZE'<>'v-f79d0c0c352f2bb2fc40e13a') || '[{"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-91f67e8b7351adcf1014135a"}, "image_url": "/assets/enbishan-menu/owner-20261025/grape-cabbage-family.webp"}, {"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-37d0336de98e6dc7d6d50959"}, "image_url": "/assets/enbishan-menu/owner-20261025/grape-cabbage-family.webp"}, {"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-7b580db54a84af523166d2da"}, "image_url": "/assets/enbishan-menu/owner-20261025/grape-cabbage-family.webp"}, {"options": {"SIZE": "v-f79d0c0c352f2bb2fc40e13a", "FLAVOUR": "v-2606b799a8a89a992bffd12e"}, "image_url": "/assets/enbishan-menu/owner-20261025/grape-cabbage-family.webp"}]'::jsonb)
WHERE brand_id='enbishan' AND id='enbishan-menu-c434c397f9072844ba9c93b4';

