UPDATE products p SET settings=jsonb_set(jsonb_set(p.settings, '{image_url}',coalesce(artwork.mapping->(p.settings->>'image_url'),p.settings->'image_url','null'::jsonb)), '{variant_images}',
 (SELECT coalesce(jsonb_agg(jsonb_set(v,'{image_url}',coalesce(artwork.mapping->(v->>'image_url'),v->'image_url'))),'[]'::jsonb) FROM jsonb_array_elements(coalesce(p.settings->'variant_images','[]'::jsonb)) v))
FROM artwork WHERE p.brand_id='enbishan' AND (artwork.mapping ? (p.settings->>'image_url') OR EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(p.settings->'variant_images','[]'::jsonb)) v WHERE artwork.mapping ? (v->>'image_url')));
